def main():
    seen = set()
    deduped = []
    for c in ROSTER:
        key = (c["slug"].lower(), c["ats"].lower())
        if key not in seen:
            seen.add(key)
            deduped.append(c)

    print(f"Total curated companies: {len(deduped)}")
    out_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "config", "companies.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(deduped, f, indent=2)
    print(f"Successfully saved {len(deduped)} companies to {out_path}")

if __name__ == "__main__":
    main()
